import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Sequence,
} from '../remotionShim';
// --- Google Fonts Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema & Types ---



export type SocialMediaTiersProps = Record<string, any>;

// --- Helper Components ---

const Bar3D: React.FC<{
  color: string;
  height: number;
  width: number;
  depth: number;
  rangeText: string;
  delay: number;
  isLast: boolean;
  labelFontSize: number;
}> = ({ color, height, width, depth, rangeText, delay, labelFontSize }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animation drivers
  const entrance = spring({
    frame: frame - delay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const textOpacity = interpolate(
    frame - delay - 10,
    [0, 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const currentHeight = interpolate(entrance, [0, 1], [0, height]);
  
  // 3D Projection Math (Oblique / Cabinet projection style)
  // Depth goes up and right
  const angle = Math.PI / 4; // 45 degrees
  const dx = depth * Math.cos(angle);
  const dy = depth * Math.sin(angle);

  // SVG Paths
  const frontPath = `M 0,${height} L ${width},${height} L ${width},${height - currentHeight} L 0,${height - currentHeight} Z`;
  
  // Side Face (Right)
  const sidePath = `
    M ${width},${height} 
    L ${width + dx},${height - dy} 
    L ${width + dx},${height - currentHeight - dy} 
    L ${width},${height - currentHeight} 
    Z
  `;

  // Top Face
  const topPath = `
    M 0,${height - currentHeight}
    L ${dx},${height - currentHeight - dy}
    L ${width + dx},${height - currentHeight - dy}
    L ${width},${height - currentHeight}
    Z
  `;

  return (
    <div style={{ position: "relative", width, height: height + dy, flexShrink: 0 }}>
      {/* Range Label above bar */}
      <div
        style={{
          position: "absolute",
          bottom: height + dy + 10, // Position above the projected top
          left: -width * 0.2,
          width: width * 1.8, // Allow text to spill over slightly
          textAlign: "center",
          fontFamily: "Lato",
          fontSize: labelFontSize,
          fontWeight: 700,
          color: "#666",
          opacity: textOpacity,
          transform: `translateY(${interpolate(entrance, [0, 1], [20, 0])}px)`,
        }}
      >
        {rangeText}
      </div>

      {/* The 3D Bar */}
      <svg
        width={width + dx}
        height={height + dy}
        viewBox={`0 0 ${width + dx} ${height + dy}`}
        style={{ overflow: "visible" }}
      >
        {/* Shadow cast by previous bar could go here, but omitted for clean loop */}
        
        {/* Side Face (Darker) */}
        <path d={sidePath} fill={color} fillOpacity={0.7} />
        
        {/* Front Face (Normal) */}
        <path d={frontPath} fill={color} />
        
        {/* Top Face (Lighter) */}
        <path d={topPath} fill={color} fillOpacity={0.4} />
      </svg>
    </div>
  );
};

const LegendItem: React.FC<{
  color: string;
  label: string;
  delay: number;
}> = ({ color, label, delay }) => {
  const frame = useCurrentFrame();
  const opacity = interpolate(frame - delay, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const translateY = interpolate(frame - delay, [0, 20], [10, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 8,
        opacity,
        transform: `translateY(${translateY}px)`,
      }}
    >
      <div
        style={{
          width: 24,
          height: 24,
          borderRadius: "50%",
          backgroundColor: color,
        }}
      />
      <span
        style={{
          fontFamily: "Lato",
          fontSize: 20,
          color: "#555",
          fontWeight: 600,
        }}
      >
        {label}
      </span>
    </div>
  );
};

// --- Main Component ---

const SocialMediaTiers: React.FC<SocialMediaTiersProps> = ({
  backgroundColor = "#F9F7F2",
  transparentBackground = false,
  durationInSeconds = 8,
  titlePrimary = "Social Media",
  titleSecondary = "FOLLOWER TIERS",
  accentColor = "#FF8BA7",
  barDepth = 40,
  barLabelFontSize = 42,
  data = [
    { label: "Nano", rangeText: "1K-10K", value: 30, color: "#C4C4C4" },
    { label: "Micro", rangeText: "10K-50K", value: 45, color: "#B3BCE5" },
    { label: "Mid-tier", rangeText: "50K-500K", value: 60, color: "#F7CE68" },
    { label: "Macro", rangeText: "500K-1M", value: 75, color: "#F06E88" },
    { label: "Mega", rangeText: "1M+", value: 95, color: "#A870F3" },
  ],
}) => {
  useFontLoader(["Montserrat", "Lato"]);
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive calculations
  const chartWidth = width * 0.85;
  const chartHeight = height * 0.45;
  const barWidth = chartWidth / data.length - (barDepth * 0.5); 
  const maxBarValue = Math.max(...data.map((d) => d.value));

  // Title Animations
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" });
  const titleSlide = interpolate(frame, [0, 20], [-20, 0], { extrapolateRight: "clamp" });
  
  // Axis Animation
  const axisWidth = interpolate(frame, [10, 40], [0, chartWidth * 1.1], {
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t), // easeOutQuad
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, alignItems: "center" }}>
      
      {/* HEADER SECTION */}
      <AbsoluteFill
        style={{
          top: height * 0.12,
          height: height * 0.15,
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Sparkle Decoration */}
        <div style={{
           opacity: titleOpacity,
           transform: `translateY(${titleSlide}px) scale(${interpolate(frame, [10,30], [0,1], {extrapolateRight:'clamp'})})`,
           marginBottom: 10
        }}>
           <svg width="40" height="40" viewBox="0 0 24 24" fill="none">
             <path d="M12 2L14.5 9.5L22 12L14.5 14.5L12 22L9.5 14.5L2 12L9.5 9.5L12 2Z" fill="#F7CE68" />
           </svg>
        </div>

        <h1
          style={{
            fontFamily: "Montserrat",
            fontSize: 56,
            color: "#666",
            margin: 0,
            opacity: titleOpacity,
            transform: `translateY(${titleSlide}px)`,
            fontWeight: 500,
          }}
        >
          {titlePrimary}
        </h1>
        <h2
          style={{
            fontFamily: "Montserrat",
            fontSize: 72,
            color: accentColor,
            margin: 0,
            opacity: titleOpacity,
            transform: `translateY(${titleSlide}px)`,
            fontWeight: 700,
            textTransform: "uppercase",
            letterSpacing: -1,
          }}
        >
          {titleSecondary}
        </h2>
      </AbsoluteFill>

      {/* CHART SECTION */}
      <div
        style={{
          position: "absolute",
          top: height * 0.35,
          width: chartWidth,
          height: chartHeight,
          display: "flex",
          alignItems: "flex-end",
          justifyContent: "space-between",
          // Padding to accommodate the 3D skew spilling out
          paddingRight: barDepth, 
        }}
      >
        {data.map((item, index) => {
          // Normalize height based on max value in dataset to fit chart area
          const normalizedHeight = (item.value / maxBarValue) * (chartHeight * 0.85);
          
          return (
            <Bar3D
              key={item.label}
              color={item.color}
              height={normalizedHeight}
              width={barWidth}
              depth={barDepth}
              rangeText={item.rangeText}
              delay={index * 5 + 15} // Staggered start
              isLast={index === data.length - 1}
              labelFontSize={barLabelFontSize}
            />
          );
        })}

        {/* X-Axis Line */}
        <div
          style={{
            position: "absolute",
            bottom: 0,
            left: -chartWidth * 0.05,
            height: 6,
            backgroundColor: "#555",
            borderRadius: 3,
            width: axisWidth,
            zIndex: 10,
          }}
        />
      </div>

      {/* LEGEND SECTION */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.12,
          width: width * 0.9,
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          gap: 25,
        }}
      >
        {data.map((item, index) => (
          <LegendItem
            key={item.label}
            color={item.color}
            label={item.label}
            delay={index * 3 + 40}
          />
        ))}
      </div>

    </AbsoluteFill>
  );
};

export default SocialMediaTiers;